WITH valid AS (SELECT id, store_name, city, opened_date, sqft, CONCAT_WS('/', city, store_name) AS city_store_name_key FROM stores WHERE opened_date >= DATE '2023-06-24') SELECT id, store_name, city, city_store_name_key, RANK() OVER (PARTITION BY city ORDER BY sqft) AS sqft_rank, NTILE(4) OVER (PARTITION BY city ORDER BY sqft DESC, id) AS sqft_bucket, NTILE(5) OVER (ORDER BY sqft DESC, id) AS sqft_bucket_2 FROM valid
